sources.app.tsx:
// Star shooter: a vertical shoot-em-up in the 8-bit palette mode. Fly the
// Kestrel along the bottom of the Lantern Belt, shoot down moths, darts, pods
// and shellbacks wave after wave, catch power-ups (S spread, R rapid fire,
// O shield, B bomb) and face the Gloom barge every fifth wave.
//
// Everything is drawn into one Uint8Array of cells handed to frameos.pixels:
// the stars are still cells whose palette entries move, and each frame only
// what moved is taken away and drawn again. Touch: the D-pad and A / B in the
// panels, or drag anywhere on the field to fly (the ship follows the finger
// by as much as it moves). Keys: arrows or WASD, Space / Z fire, X bomb,
// Enter or P pause. GPIO buttons by the "Buttons" setting.
import { blit, clip, restore, target, textCenter, textWidth, title } from './gfx'
import {
  A, B, START, TAP, dragging, handle, held as heldNow, lastTapX, lastTapY, press, ptrX, ptrY, releaseAll,
  setButtons, setHitTest, take, usingKeyboard,
} from './input'
import { drawControls, hit, layout, updateControls } from './controls'
import {
  UI_ACCENT, UI_BLINK, UI_DIM, UI_PANEL, UI_SHADOW, UI_TEXT, UI_TITLE, addScore, blink, cellSize, choice, clockReset,
  drawGameOver, drawPause, drawScores, drawSlowCard, fastScreen, fitScale, highContrast, pauseChoice, readScores,
  reseed, stepsDue, uiColors,
} from './ui'
import { CAPSULE, FLAME, MY_SHIELD, SHIELD, SPACE, THEME, gameColors } from './art'
import { ROSTER, S, FIELD, drawHud, frame, setBest, newGame, redraw, resume, setField, snapshot, spaceColor, stars } from './game'

const STEP_MS = 1000 / 60
const IDLE_MS = 30000 // the title and game over animate this long, then sleep until a touch

let cells: Uint8Array | null = null
let bg: Uint8Array = new Uint8Array(1)
let cols = 0
let rows = 0
let px = 4
let width = 0
let height = 0
let L: any = null
const pal = new Uint32Array(256)
// frameos.pixels' options, one object kept rather than one made a frame.
const opts = { width: 1, height: 1, pixelSize: 1 }

type Mode = 'title' | 'play' | 'pause' | 'over' | 'slow'
let mode: Mode = 'title'
let idleFrom = 0
let shownHeld = 0
let scores: number[] = []
let rank = -1
let overAt = 0
let overReady = false
let titlePage = -1
let snapAt = 0

// Settings, read from the scene's state about once a second.
let settingsAt = 0
let layoutKey = ''
let hc = false
let fast = true
let difficulty = 1
let lives = 3
let autoFire = 'auto'
let startWave = 1

export function get(app, context) {
  const now = Date.now()
  const w = context.imageWidth || app.frame.width
  const h = context.imageHeight || app.frame.height
  if (!cells || w !== width || h !== height || now - settingsAt > 1000) settings(app, w, h, now)
  if (mode === 'slow') {
    frameos.setNextSleep(3600)
    return frameos.pixels(cells!, pal, opts)
  }
  let pressed = take()
  const held = heldNow()
  // A press that changes the mode is spent on that.
  if (mode === 'title') {
    if (pressed & (A | START | TAP)) {
      start(now)
      pressed = 0
    } else titleScreen(now)
  } else if (mode === 'pause') {
    let choice = 0
    if (pressed & TAP) choice = pauseChoice(lastTapX() / px, lastTapY() / px)
    if (choice === 1 || pressed & (A | START)) unpause(now)
    else if (choice === 2 || pressed & B) quit(now)
    pressed = 0
  } else if (mode === 'over') {
    if (!overReady && now - overAt > 1200) {
      overReady = true
      overDialog()
    }
    if (overReady && pressed & (A | START | TAP)) start(now)
    else if (overReady && pressed & B) quit(now)
    pressed = 0
  }
  if (mode === 'play') {
    if (pressed & START) pause()
    else play(now, held, pressed)
  }
  colors(now)
  if (L && held !== shownHeld) {
    updateControls(L, shownHeld, held)
    shownHeld = held
  }
  if (mode === 'pause' || ((mode === 'title' || mode === 'over') && now - idleFrom > IDLE_MS)) frameos.setNextSleep(3600)
  return frameos.pixels(cells!, pal, opts)
}

export function onEvent(app, context) {
  const event = context.event
  const payload = context.payload || {}
  if (event === 'close') {
    // Every finger lets go, and a game going on pauses.
    releaseAll()
    if (mode === 'play') press(START)
    return false
  }
  if (event === 'open') return mode !== 'slow'
  if (event === 'back') press(START)
  else if (event === 'forward') press(mode === 'play' ? 0 : A)
  else if (handle(event, payload) < 0) return false
  idleFrom = Date.now()
  // While playing the frame draws many times a second anyway.
  return mode !== 'play' && mode !== 'slow'
}

// --- settings and the layout -----------------------------------------------------------

function settings(app: any, w: number, h: number, now: number) {
  settingsAt = now
  const st = app.state
  const frame = app.frame
  const fresh = !cells
  if (fresh) scores = readScores(st.highScores)
  hc = highContrast(st.contrast, frame)
  fast = fastScreen(frame)
  difficulty = ['easy', 'normal', 'hard'].indexOf(choice(st.difficulty, ['normal', 'easy', 'hard']))
  lives = Number(choice(st.lives, ['3', '5', '1']))
  autoFire = choice(st.autoFire, ['auto', 'on', 'off'])
  startWave = Number(choice(st.startWave, ['1', '5', '10', '15']))
  setButtons(st.buttons)
  const size = cellSize(st.pixelSize, w, h, 120)
  const show = choice(st.controls, ['on', 'off']) === 'on'
  const vertical = choice(st.vertical, ['auto', 'on', 'off'])
  const upDown = vertical === 'on' || (vertical === 'auto' && h > w * 1.15)
  gameColors(pal, hc)
  uiColors(pal, THEME, hc)
  const key = [w, h, size, show, upDown, fast].join(':')
  if (key === layoutKey && !fresh) return
  layoutKey = key
  width = w
  height = h
  px = size
  cols = Math.max(40, Math.floor(w / px))
  rows = Math.max(40, Math.floor(h / px))
  cells = new Uint8Array(cols * rows)
  opts.width = cols
  opts.height = rows
  opts.pixelSize = px
  bg = new Uint8Array(cols * rows)
  target(cells, cols, rows)
  if (!fast) {
    mode = 'slow'
    drawSlowCard(cols, rows, 'STAR SHOOTER', ['A SHOOT-EM-UP FOR A FAST SCREEN:', 'LCD OR HDMI.', '',
      'ON E-PAPER IT SLEEPS HERE.'], scores)
    return
  }
  L = layout(cols, rows, px, upDown ? 4 : 2, 2, show)
  const layoutNow = L
  setHitTest((x, y) => hit(layoutNow, x, y))
  setField(cells, bg, cols, rows, L.x, L.y, L.w, L.h, upDown)
  if (fresh) {
    reseed(now)
    idleFrom = now
    // An interpreter dropped mid-game (an ESP32 short of memory): back to the
    // wave it was in, paused.
    const snap = frameos.recall('snap') as any
    if (snap && snap.wave) {
      resume(snap, difficulty)
      mode = 'pause'
    } else mode = 'title'
  } else if (mode === 'play') mode = 'pause'
  if (mode === 'slow') mode = 'title'
  drawEverything(now)
}

/** The whole screen for the mode: after a new layout, a dialog closing. */
function drawEverything(now: number) {
  cells!.fill(UI_PANEL)
  clip(0, 0, cols, rows)
  drawControls(L!, heldNow())
  shownHeld = heldNow()
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  restore(bg, fx, fy, fw, fh)
  setBest(scores.length ? scores[0] : 0)
  drawHud(true)
  if (mode === 'title') {
    titlePage = -1
    titleScreen(now)
  } else if (mode === 'pause') {
    redraw()
    pauseDialog()
  } else if (mode === 'over') {
    redraw()
    overDialog()
  } else redraw()
}

// --- the modes -----------------------------------------------------------------------------

function start(now: number) {
  newGame(lives, difficulty, startWave)
  mode = 'play'
  rank = -1
  clockReset(now)
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  restore(bg, fx, fy, fw, fh)
  redraw()
  drawHud(true)
}

function play(now: number, held: number, pressed: number) {
  const steps = stepsDue(now, STEP_MS, 4)
  const auto = autoFire === 'on' || (autoFire === 'auto' && !usingKeyboard())
  const fx = FIELD[0]
  const fy = FIELD[1]
  const drag = dragging()
  frame(steps, held, pressed, auto, drag, drag >= 0 ? ptrX[drag] / px - fx : 0, drag >= 0 ? ptrY[drag] / px - fy : 0)
  drawHud(false)
  if (S.over) {
    mode = 'over'
    overAt = now
    overReady = false
    idleFrom = now
    rank = addScore(scores, S.score)
    frameos.remember('snap', null)
    overDialog()
    return
  }
  if (now - snapAt > 1000) {
    snapAt = now
    frameos.remember('snap', snapshot())
  }
}

function pause() {
  mode = 'pause'
  releaseAll()
  frameos.remember('snap', snapshot())
  pauseDialog()
}

function unpause(now: number) {
  mode = 'play'
  clockReset(now)
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  redraw()
}

function quit(now: number) {
  mode = 'title'
  S.wave = 0
  S.score = 0
  drawHud(true)
  idleFrom = now
  frameos.remember('snap', null)
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  restore(bg, fx, fy, fw, fh)
  titlePage = -1
  titleScreen(now)
}

function pauseDialog() {
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  drawPause(fx, fy, fw, fh, 'ENTER OR P: RESUME')
}

function overDialog() {
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  restore(bg, fx, fy, fw, fh)
  drawGameOver(fx, fy, fw, fh, 'GAME OVER', ['SCORE ' + S.score, 'WAVE ' + S.wave], rank, scores, overReady)
}

/** The title: the name, then the enemies and the high scores taking turns. */
function titleScreen(now: number) {
  const page = ((now - idleFrom) / 5000) & 1
  if (page === titlePage) return
  const fx = FIELD[0]
  const fy = FIELD[1]
  const fw = FIELD[2]
  const fh = FIELD[3]
  clip(fx, fy, fw, fh)
  restore(bg, fx, fy, fw, fh)
  titlePage = page
  const cx = fx + (fw >> 1)
  // The name takes at most a third of the field's height.
  const big = Math.max(1, Math.min(fitScale(7, fw - 6, 4), Math.floor(fh / 3 / 12)))
  let y = fy + Math.max(2, (fh / 14) | 0)
  if (textWidth('STAR SHOOTER', big) <= fw - 6) {
    title('STAR SHOOTER', cx, y, big, UI_TITLE, UI_SHADOW)
    y += 7 * big
  } else {
    title('STAR', cx, y, big, UI_TITLE, UI_SHADOW)
    title('SHOOTER', cx, y + 6 * big, big, UI_TITLE, UI_SHADOW)
    y += 13 * big
  }
  const small = fitScale(24, fw - 4, 2)
  textCenter('HOLD THE LANTERN BELT', cx, y, small, UI_ACCENT)
  y += 9 * small
  const bottom = fy + fh - 8 * small - (fh > 90 ? 7 : 0)
  if (page === 0) {
    // The roster: each enemy, its name and its points.
    const rowH = Math.max(11, 9 * small)
    for (let i = 0; i < ROSTER.length && y + rowH <= bottom - 2; i++) {
      const [spr, name, points] = ROSTER[i]
      const line = name + ' ' + points
      const lw = 14 + textWidth(line, small)
      const x = cx - (lw >> 1)
      blit(spr, x + ((11 - spr.w) >> 1), y + ((rowH - spr.h) >> 1) - 1)
      textCenter(line, x + 14 + (textWidth(line, small) >> 1), y + ((rowH - 5 * small) >> 1) - 1, small, UI_TEXT)
      y += rowH
    }
  } else drawScores(scores, cx, y + 2, small)
  textCenter('TAP OR PRESS A', cx, bottom, small, UI_BLINK)
  if (fh > 90 && textWidth('A FIRE   B BOMB', 1) < fw) textCenter('A FIRE   B BOMB', cx, bottom + 7 * small, 1, UI_DIM)
}

// --- colors: what moves without a cell changing ------------------------------------------------

function colors(now: number) {
  const space = spaceColor(hc)
  pal[SPACE] = space
  stars(pal, now, hc, space)
  if (!hc) {
    pal[FLAME] = (now >> 6) & 1 ? 0xffc23a : 0xff6a1f
    const k = (now >> 7) & 3
    pal[CAPSULE] = k === 0 ? 0xffffff : k === 1 ? 0xffd84a : k === 2 ? 0x53ff8a : 0x5fd4ff
    pal[MY_SHIELD] = (now >> 7) & 1 ? 0x7fe7ff : 0x2f9fd0
    pal[SHIELD] = (now >> 8) & 1 ? 0x9ff3ff : 0x4fc7e8
  }
  blink(pal, now, hc ? 0xffffff : THEME.text, hc ? 0 : THEME.dim)
}

sources.art.ts:
// Star shooter's colors and sprites. Each palette index is one thing's color,
// so a flash, a flicker or the stars' motion is a palette change and costs
// no cell. Sprites are compact strings, left half and middle column only:
// the right half is the left one turned over.
import { glyphBits, sprite } from './gfx'

export const SPACE = 0
export const HUD = 1
export const SHIP = 2
export const SHIP_SHADE = 3
export const COCKPIT = 4
export const FLAME = 5
export const FLAME2 = 6
export const SHOT = 7
export const SHOT_CORE = 8
export const BULLET = 9
export const BULLET_CORE = 10
export const MOTH = 11
export const MOTH_WING = 12
export const EYE = 13
export const DART = 14
export const DART_SHADE = 15
export const DART_TIP = 16
export const POD = 17
export const POD_SHADE = 18
export const POD_CORE = 19
export const SHELL = 20
export const SHELL_SHADE = 21
export const SHIELD = 22
export const HULL = 23
export const HULL_DARK = 24
export const GLOW = 25
export const GLOW2 = 26
export const FLASH = 27
export const SPARK = 28 // .. 31, hot to cold
export const CAPSULE = 32
export const P_SPREAD = 33
export const P_RAPID = 34
export const P_SHIELD = 35
export const P_BOMB = 36
export const MY_SHIELD = 37
export const HUD_TEXT = 38
export const HUD_DIM = 39
export const BAR = 40
export const BAR_BACK = 41

// The stars: three layers, each a range of indexes laid down every column
// that has stars, so one bright entry walking through the range is a star
// falling down that column (see stars() in game.ts).
export const FAR = 64
export const FAR_P = 40
export const MID = FAR + FAR_P
export const MID_P = 28
export const NEAR = MID + MID_P
export const NEAR_P = 20

const COLORS = [
  0x070b1e, 0x0f1530, 0xdce6f2, 0x6f82a8, 0x45d4ff, 0xffc23a, 0xff5a1f, 0xfff27a, 0xffffff, 0xff4d8d,
  0xffd6e6, 0x9b5cff, 0xd6a4ff, 0xffe14d, 0xff7a3d, 0xa8361a, 0xffd78a, 0x3ddc97, 0x1d7a55, 0xeaff7a,
  0x4aa3ff, 0x1f4f99, 0x9ff3ff, 0x707b99, 0x363e57, 0xff3d6e, 0xffb3c6, 0xffffff, 0xffffff, 0xffe066,
  0xff8a2a, 0x8a1f2a, 0xffffff, 0x53ff8a, 0xffd84a, 0x5fd4ff, 0xff6a6a, 0x7fe7ff, 0xe8eefc, 0x7d88b0,
  0xff3d6e, 0x3a1626,
]
// In black and white: 1 white, 0 black. Bodies white, shading and details
// black, so every shape keeps its outline.
const INK = '001001111101101011101011010111101111111110'

export const THEME = {
  title: [0xfff6a0, 0xffd84a, 0xffa53a, 0xff6a3d, 0xe8366a],
  shadow: 0x2a1450,
  panel: 0x10142c,
  edge: 0x2c3566,
  border: 0x5868a8,
  face: 0x232b56,
  lit: 0x45d4ff,
  icon: 0xc8d4ff,
  iconLit: 0x0a1030,
  text: 0xe8eefc,
  dim: 0x8a95c0,
  dialog: 0x141a3a,
  dialogEdge: 0x6b7cc4,
  accent: 0x45d4ff,
  good: 0xffd84a,
}

/** The game's part of the palette (0..223), in color or black and white. */
export function gameColors(pal: Uint32Array, hc: boolean) {
  for (let i = 0; i < COLORS.length; i++) pal[i] = hc ? (INK[i] === '1' ? 0xffffff : 0) : COLORS[i]
}

/** Mirrors a left half (with the middle column) into a whole sprite. */
function sym(rows: string[]): string {
  return rows.map((r) => r + r.slice(0, -1).split('').reverse().join('')).join('|')
}

// The Kestrel, the player's ship.
export const KESTREL = sprite(
  sym(['....b', '...bc', '...bc', '..sbb', '.sbbb', 'sbbsb', 'sbs.b', 's..sf', '....f']),
  'bscf', [SHIP, SHIP_SHADE, COCKPIT, FLAME])
// Moths swoop down in a line, wings beating.
export const MOTH_A = sprite(sym(['w....', 'ww.bb', 'wwbbe', '.wbbb', '..wbb', '..w.b', '.w...']), 'wbe', [MOTH_WING, MOTH, EYE])
export const MOTH_B = sprite(sym(['.....', '.w.bb', 'wwbbe', 'wwbbb', 'w.wbb', '..w.b', '.....']), 'wbe', [MOTH_WING, MOTH, EYE])
// Darts hover, then dive at you.
export const DART_S = sprite(sym(['s...', 'sb..', 'sbbt', '.bbt', '.sbt', '..bt', '..sb', '...b', '...t']), 'sbt',
  [DART_SHADE, DART, DART_TIP])
// Pods settle and spit three ways.
export const POD_S = sprite(sym(['..sss', '.sggg', 'sggcc', 'sgcgg', 'sgcgc', 'sggcc', '.sggg', '..s.s']), 'sgc',
  [POD_SHADE, POD, POD_CORE])
// Shellbacks carry a shield underneath.
export const SHELL_S = sprite(sym(['...bbb', '.bbsss', 'bbsbbb', 'bsbbeb', 'bsbbbb', '.bsbbb', '..bs.s', '..b...']), 'bse',
  [SHELL, SHELL_SHADE, EYE])
export const SHELL_GUARD = sprite(sym(['.zzzzzz', 'zz.....']), 'z', [SHIELD])
// The Gloom barge, every fifth wave.
export const BARGE = sprite(sym([
  '........hhhhh', '.....hhhddddd', '...hhddhhhhhh', '.hhdhhhhhgggg', 'hhdhhhhhgGGGG', 'hdhhdhhhgGGee',
  'hdhhdhhhgGGee', 'hhdhhhhhgGGGG', '.hhdhhhhhgggg', '..hhddhhhhhhh', '..hd.hhdddddd', '..hd..hh.d..d',
  '..g....g.g..g']), 'hdgGe', [HULL, HULL_DARK, GLOW, GLOW2, EYE])
// The player's shield: a ring around the ship.
export const RING = sprite(sym(['...rrrr', '.rr....', 'r......', 'r......', 'r......', 'r......', 'r......', '.r.....',
  '..rr...', '....rrr']), 'r', [MY_SHIELD])
// Shots and bullets.
export const SHOT_S = sprite('c|s|s', 'cs', [SHOT_CORE, SHOT])
export const BULLET_S = sprite('cb|bb', 'cb', [BULLET_CORE, BULLET])
// A small ship and a bomb for the score strip.
export const LIFE_S = sprite(sym(['..b', '.bb', 'bbb', 'b.b']), 'b', [SHIP])
export const BOMB_S = sprite('.bb.|bbbb|bbbb|.bb.', 'b', [P_BOMB])

/** A power-up capsule: a ring around the letter, in its color. */
function capsule(letter: string, color: number) {
  const rows: string[] = []
  const bits = glyphBits(letter)
  rows.push('.rrr.')
  for (let r = 0; r < 5; r++) {
    let line = 'r'
    for (let c = 0; c < 3; c++) line += bits & (1 << (14 - r * 3 - c)) ? 'l' : '.'
    rows.push(line + 'r')
  }
  rows.push('.rrr.')
  return sprite(rows.join('|'), 'rl', [CAPSULE, color])
}
export const CAPSULES = [capsule('S', P_SPREAD), capsule('R', P_RAPID), capsule('O', P_SHIELD), capsule('B', P_BOMB)]

sources.game.ts:
// Star shooter's game: the field, the ship, the waves, every pool of shots,
// bullets, sparks and power-ups, and drawing them. Everything moves in fixed
// steps of 1/60 s. Each frame puts back what moving things covered (from the
// background layer, the stars), runs the steps and draws them again, so the
// panel only rewrites the cells that changed.
import { blit, clip, fill, restore, target, text, textCenter, textWidth, title, unblit } from './gfx'
import { A, B, DOWN, LEFT, RIGHT, UP } from './input'
import { UI_SHADOW, UI_TITLE, rfloat, rint } from './ui'
import {
  BAR, BAR_BACK, BARGE, BOMB_S, BULLET_S, CAPSULES, DART_S, FAR, FAR_P, HUD, HUD_DIM, HUD_TEXT, KESTREL, LIFE_S,
  MID, MID_P, MOTH_A, MOTH_B, NEAR, NEAR_P, POD_S, RING, SHELL_GUARD, SHELL_S, SHOT_S, SPACE, SPARK, FLASH,
} from './art'

// --- the field ------------------------------------------------------------------

let cells: Uint8Array = new Uint8Array(1)
let bg: Uint8Array = new Uint8Array(1)
let cols = 1
let rows = 1
/** The field (where things fly) and the score strip above it, in cells. */
let FX = 0
let FY = 0
let FW = 1
let FH = 1
let HY = 0
let HH = 0
let canMoveUp = false

/** Lays the game out: the score strip at the top of the play area, the field below. */
export function setField(c: Uint8Array, layer: Uint8Array, gridCols: number, gridRows: number,
    x: number, y: number, w: number, h: number, upDown: boolean) {
  cells = c
  bg = layer
  cols = gridCols
  rows = gridRows
  HH = 7
  HY = y
  FX = x
  FY = y + HH
  FW = w
  FH = h - HH
  canMoveUp = upDown
  FIELD[0] = FX
  FIELD[1] = FY
  FIELD[2] = FW
  FIELD[3] = FH
  makeStars()
}

/** The field's x, y, width and height, for the screens drawn over it. */
export const FIELD = new Int16Array(4)

// --- the stars ------------------------------------------------------------------

// Columns with stars carry a layer's range of indexes down their length, so
// one bright entry walking through the range falls down every such column.
function starCell(x: number, y: number): number {
  const h = ((x * 73856093) ^ (x * 19349663 >>> 7)) >>> 0
  const layer = h % 23
  const off = (h >>> 8) & 255
  if (layer < 3) return FAR + ((y + off) % FAR_P)
  if (layer < 5) return MID + ((y + off) % MID_P)
  if (layer < 6) return NEAR + ((y + off) % NEAR_P)
  return SPACE
}

function makeStars() {
  bg.fill(SPACE)
  for (let x = 0; x < FW; x++) {
    if (starCell(x, 0) === SPACE && starCell(x, 1) === SPACE) continue
    for (let y = 0; y < FH; y++) bg[(FY + y) * cols + FX + x] = starCell(x, y)
  }
}

/** Puts the stars back over a rectangle of the field, in the layer and the cells. */
function clearLayer(x: number, y: number, w: number, h: number) {
  for (let yy = y; yy < y + h; yy++) {
    if (yy < FY || yy >= FY + FH) continue
    for (let xx = x; xx < x + w; xx++) {
      if (xx < FX || xx >= FX + FW) continue
      bg[yy * cols + xx] = starCell(xx - FX, yy - FY)
    }
  }
  restore(bg, x, y, w, h)
}

/** The stars' palette for this moment: each layer at its own speed, a trail above each star. */
export function stars(pal: Uint32Array, now: number, hc: boolean, space: number) {
  layer(pal, FAR, FAR_P, ((now * 7) / 1000) | 0, hc ? 0xffffff : 0x5a6488, hc ? space : 0x262c48, space)
  layer(pal, MID, MID_P, ((now * 16) / 1000) | 0, hc ? 0xffffff : 0xa9b8e6, hc ? space : 0x3a4470, space)
  layer(pal, NEAR, NEAR_P, ((now * 34) / 1000) | 0, 0xffffff, hc ? 0xffffff : 0x8090c8, space)
}

function layer(pal: Uint32Array, base: number, period: number, at: number, star: number, trail: number, space: number) {
  const head = at % period
  for (let j = 0; j < period; j++) {
    const d = (j - head + period) % period
    pal[base + j] = d === 0 ? star : d === period - 1 ? trail : space
  }
}

// A sine table: Math.sin is a native call, dear on an ESP32 in a loop.
const SIN = new Float32Array(256)
for (let i = 0; i < 256; i++) SIN[i] = Math.sin((i * Math.PI) / 128)

// --- the game's state -------------------------------------------------------------

const T_MOTH = 1
const T_DART = 2
const T_POD = 3
const T_SHELL = 4
const T_BOSS = 5
const SPRITES = [MOTH_A, MOTH_B, DART_S, POD_S, SHELL_S, BARGE]
const POINTS = [0, 100, 150, 250, 400, 5000]

const NE = 28
const eT = new Uint8Array(NE)
const eX = new Float32Array(NE)
const eY = new Float32Array(NE)
const eVX = new Float32Array(NE)
const eVY = new Float32Array(NE)
const eHP = new Int16Array(NE)
const eAge = new Int32Array(NE)
const eA = new Float32Array(NE) // a parameter: a moth's path centre, a dart's or a pod's height
const eB = new Float32Array(NE) // another: a moth's phase and swing
const eFire = new Int16Array(NE)
const eFlash = new Uint8Array(NE)
const eGuard = new Int8Array(NE)
const eSpr = new Int8Array(NE).fill(-1) // what was drawn, to take away
const eDX = new Int16Array(NE)
const eDY = new Int16Array(NE)
const eDG = new Uint8Array(NE)

const NS = 30 // the ship's shots
const sOn = new Uint8Array(NS)
const sX = new Float32Array(NS)
const sY = new Float32Array(NS)
const sVX = new Float32Array(NS)
const sDrawn = new Uint8Array(NS)
const sDX = new Int16Array(NS)
const sDY = new Int16Array(NS)

const NB = 48 // the enemies' bullets
const bOn = new Uint8Array(NB)
const bX = new Float32Array(NB)
const bY = new Float32Array(NB)
const bVX = new Float32Array(NB)
const bVY = new Float32Array(NB)
const bDrawn = new Uint8Array(NB)
const bDX = new Int16Array(NB)
const bDY = new Int16Array(NB)

const NP = 72 // sparks
const pLife = new Uint8Array(NP)
const pX = new Float32Array(NP)
const pY = new Float32Array(NP)
const pVX = new Float32Array(NP)
const pVY = new Float32Array(NP)
const pDrawn = new Int32Array(NP).fill(-1)

const NU = 4 // power-ups falling
const uOn = new Uint8Array(NU)
const uKind = new Uint8Array(NU)
const uX = new Float32Array(NU)
const uY = new Float32Array(NU)
const uDrawn = new Int8Array(NU).fill(-1)
const uDX = new Int16Array(NU)
const uDY = new Int16Array(NU)

const NQ = 24 // enemies about to come in: steps to wait, type, x, a parameter
const qWait = new Int16Array(NQ)
const qType = new Uint8Array(NQ)
const qX = new Float32Array(NQ)
const qA = new Float32Array(NQ)

export const S = {
  score: 0,
  lives: 3,
  wave: 0,
  bombs: 2,
  spread: 0,
  rapid: 0, // steps of rapid fire left
  shield: false,
  difficulty: 1,
  over: false,
}
let shipX = 0
let shipY = 0
let shipAlive = true
let shipDrawn = false
let shipDX = 0
let shipDY = 0
let ringDrawn = false
let invulnerable = 0
let respawn = 0
let endIn = 0
let cooldown = 0
let nextLife = 30000
let squads = 0
let squadIn = 0
let banner = 0
let bannerBox = [0, 0, 0, 0]
let bossWave = false
let bossHP = 0
let bossMax = 1
let flash = 0
let step = 0
let dragFromX = 0
let dragFromY = 0
let dragging = false

// --- starting ------------------------------------------------------------------------

export function newGame(lives: number, difficulty: number, wave: number) {
  S.score = 0
  S.lives = lives
  S.wave = 0
  S.bombs = 2
  S.spread = 0
  S.rapid = 0
  S.shield = false
  S.difficulty = difficulty
  S.over = false
  nextLife = 30000
  startWave(wave)
}

/** A wave from its start (a new one, or the one a restored game was in). */
export function startWave(n: number) {
  clearAll()
  S.wave = n
  bossWave = n % 5 === 0
  squads = bossWave ? 1 : Math.min(9, 3 + (n >> 1))
  squadIn = 100
  placeShip()
  showBanner(bossWave ? 'GLOOM BARGE' : '')
}

function placeShip() {
  shipX = (FW - KESTREL.w) / 2
  shipY = FH - KESTREL.h - 3
  shipAlive = true
  invulnerable = 150
  respawn = 0
  dragging = false
}

function clearAll() {
  eT.fill(0)
  sOn.fill(0)
  bOn.fill(0)
  pLife.fill(0)
  uOn.fill(0)
  qWait.fill(-1)
  endIn = 0
  flash = 0
  bossHP = 0
}

function showBanner(sub: string) {
  hideBanner()
  const big = Math.max(1, Math.min(3, Math.floor(FW / 40)))
  const head = 'WAVE ' + S.wave
  const w = Math.max(textWidth(head, big), textWidth(sub, 1)) + 4
  const h = 5 * big + (sub ? 9 : 2)
  const x = FX + ((FW - w) >> 1)
  const y = FY + ((FH * 0.38) | 0)
  bannerBox = [x, y, w, h + 2]
  // Into the background layer, so whatever flies over it puts it back.
  target(bg, cols, rows)
  clip(FX, FY, FW, FH)
  title(head, x + (w >> 1), y, big, UI_TITLE, UI_SHADOW)
  if (sub) textCenter(sub, x + (w >> 1), y + 5 * big + 4, 1, HUD_TEXT)
  target(cells, cols, rows)
  clip(FX, FY, FW, FH)
  restore(bg, x, y, w, h + 2)
  banner = 110
}

function hideBanner() {
  if (!bannerBox[2]) return
  clearLayer(bannerBox[0], bannerBox[1], bannerBox[2], bannerBox[3])
  bannerBox = [0, 0, 0, 0]
}

// --- one frame ---------------------------------------------------------------------------

/**
 * Takes away what was drawn, runs `steps` steps with the buttons `held` (and
 * the presses since the last frame, `pressed`), and draws it all again.
 * `drag` is a finger on the field: its id, or -1, and where it is in cells.
 */
export function frame(steps: number, held: number, pressed: number, auto: boolean, drag: number, dragX: number, dragY: number) {
  clip(FX, FY, FW, FH)
  eraseAll()
  if (drag >= 0) {
    if (!dragging) {
      dragging = true
      dragFromX = dragX - shipX
      dragFromY = dragY - shipY
    }
  } else dragging = false
  for (let i = 0; i < steps; i++) {
    tick(held, pressed, auto, dragX, dragY)
    pressed = 0
  }
  drawAll()
}

/** The whole field again (after a dialog covered it). */
export function redraw() {
  clip(FX, FY, FW, FH)
  restore(bg, FX, FY, FW, FH)
  eSpr.fill(-1)
  sDrawn.fill(0)
  bDrawn.fill(0)
  pDrawn.fill(-1)
  uDrawn.fill(-1)
  shipDrawn = false
  ringDrawn = false
  drawAll()
}

function eraseAll() {
  if (shipDrawn) {
    unblit(KESTREL, shipDX, shipDY, bg)
    shipDrawn = false
  }
  if (ringDrawn) {
    unblit(RING, shipDX - 2, shipDY - 1, bg)
    ringDrawn = false
  }
  for (let i = 0; i < NE; i++) {
    const s = eSpr[i]
    if (s < 0) continue
    unblit(SPRITES[s], eDX[i], eDY[i], bg)
    if (eDG[i]) unblit(SHELL_GUARD, eDX[i] - 1, eDY[i] + SHELL_S.h, bg)
    eSpr[i] = -1
    eDG[i] = 0
  }
  for (let i = 0; i < NS; i++) if (sDrawn[i]) {
    restore(bg, sDX[i], sDY[i], 1, 3)
    sDrawn[i] = 0
  }
  for (let i = 0; i < NB; i++) if (bDrawn[i]) {
    restore(bg, bDX[i], bDY[i], 2, 2)
    bDrawn[i] = 0
  }
  for (let i = 0; i < NU; i++) if (uDrawn[i] >= 0) {
    restore(bg, uDX[i], uDY[i], 5, 7)
    uDrawn[i] = -1
  }
  for (let i = 0; i < NP; i++) {
    const at = pDrawn[i]
    if (at >= 0) {
      cells[at] = bg[at]
      pDrawn[i] = -1
    }
  }
}

function drawAll() {
  for (let i = 0; i < NU; i++) {
    if (!uOn[i]) continue
    uDX[i] = (FX + uX[i]) | 0
    uDY[i] = (FY + uY[i]) | 0
    blit(CAPSULES[uKind[i]], uDX[i], uDY[i])
    uDrawn[i] = uKind[i]
  }
  for (let i = 0; i < NE; i++) {
    const t = eT[i]
    if (!t) continue
    const s = t === T_MOTH ? ((eAge[i] >> 3) & 1) : t === T_DART ? 2 : t === T_POD ? 3 : t === T_SHELL ? 4 : 5
    const x = (FX + eX[i]) | 0
    const y = (FY + eY[i]) | 0
    blit(SPRITES[s], x, y, eFlash[i] ? FLASH : 255)
    eSpr[i] = s
    eDX[i] = x
    eDY[i] = y
    if (t === T_SHELL && eGuard[i] > 0) {
      blit(SHELL_GUARD, x - 1, y + SHELL_S.h, eFlash[i] ? FLASH : 255)
      eDG[i] = 1
    }
  }
  for (let i = 0; i < NB; i++) {
    if (!bOn[i]) continue
    const x = (FX + bX[i]) | 0
    const y = (FY + bY[i]) | 0
    blit(BULLET_S, x, y)
    bDX[i] = x
    bDY[i] = y
    bDrawn[i] = 1
  }
  for (let i = 0; i < NS; i++) {
    if (!sOn[i]) continue
    const x = (FX + sX[i]) | 0
    const y = (FY + sY[i]) | 0
    blit(SHOT_S, x, y)
    sDX[i] = x
    sDY[i] = y
    sDrawn[i] = 1
  }
  // The ship blinks while it cannot be hit.
  if (shipAlive && (invulnerable === 0 || ((invulnerable >> 2) & 1) === 0)) {
    shipDX = (FX + shipX) | 0
    shipDY = (FY + shipY) | 0
    blit(KESTREL, shipDX, shipDY)
    shipDrawn = true
    if (S.shield) {
      blit(RING, shipDX - 2, shipDY - 1)
      ringDrawn = true
    }
  }
  for (let i = 0; i < NP; i++) {
    const life = pLife[i]
    if (!life) continue
    const x = (FX + pX[i]) | 0
    const y = (FY + pY[i]) | 0
    if (x < FX || y < FY || x >= FX + FW || y >= FY + FH) continue
    const at = y * cols + x
    cells[at] = SPARK + (life > 18 ? 0 : life > 11 ? 1 : life > 5 ? 2 : 3)
    pDrawn[i] = at
  }
}

// --- one step -----------------------------------------------------------------------------

function tick(held: number, pressed: number, auto: boolean, dragX: number, dragY: number) {
  step++
  if (flash) flash--
  if (banner && --banner === 0) hideBanner()
  moveShip(held, pressed, auto, dragX, dragY)
  spawn()
  moveEnemies()
  moveShots()
  moveBullets()
  movePowerUps()
  moveSparks()
  if (endIn && --endIn === 0) S.over = true
}

function moveShip(held: number, pressed: number, auto: boolean, dragX: number, dragY: number) {
  if (!shipAlive) {
    if (respawn && --respawn === 0) {
      if (S.lives > 0) placeShip()
      else endIn = 30
    }
    return
  }
  if (invulnerable) invulnerable--
  const speed = 1.05
  if (dragging) {
    // The ship follows the finger by as much as it moved, quickly but not at once.
    const tx = dragX - dragFromX
    const ty = dragY - dragFromY
    const dx = tx - shipX
    const dy = ty - shipY
    shipX += dx > 3 ? 3 : dx < -3 ? -3 : dx
    if (canMoveUp) shipY += dy > 3 ? 3 : dy < -3 ? -3 : dy
  } else {
    if (held & LEFT) shipX -= speed
    if (held & RIGHT) shipX += speed
    if (canMoveUp && held & UP) shipY -= speed
    if (canMoveUp && held & DOWN) shipY += speed
  }
  const maxX = FW - KESTREL.w
  if (shipX < 0) shipX = 0
  if (shipX > maxX) shipX = maxX
  const top = canMoveUp ? FH * 0.3 : FH - KESTREL.h - 3
  if (shipY < top) shipY = top
  if (shipY > FH - KESTREL.h - 1) shipY = FH - KESTREL.h - 1
  if (cooldown) cooldown--
  if ((auto || held & A || pressed & A) && cooldown === 0) fire()
  if (pressed & B) bomb()
}

function fire() {
  cooldown = S.rapid ? 5 : 10
  const x = shipX + 4
  const y = shipY - 2
  shot(x, y, 0)
  if (S.spread) {
    shot(x - 2, y + 2, -0.45)
    shot(x + 2, y + 2, 0.45)
  }
}

function shot(x: number, y: number, vx: number) {
  for (let i = 0; i < NS; i++) {
    if (sOn[i]) continue
    sOn[i] = 1
    sX[i] = x
    sY[i] = y
    sVX[i] = vx
    return
  }
}

function bomb() {
  if (S.bombs <= 0 || !shipAlive) return
  S.bombs--
  flash = 14
  bOn.fill(0)
  for (let i = 0; i < NE; i++) if (eT[i]) hurt(i, eT[i] === T_BOSS ? 12 : 8)
}

function moveShots() {
  for (let i = 0; i < NS; i++) {
    if (!sOn[i]) continue
    sY[i] -= 2.6
    sX[i] += sVX[i]
    if (sY[i] < -3 || sX[i] < 0 || sX[i] >= FW) {
      sOn[i] = 0
      continue
    }
    const x = sX[i]
    const y = sY[i]
    for (let e = 0; e < NE; e++) {
      const t = eT[e]
      if (!t) continue
      const spr = SPRITES[t === T_MOTH ? 0 : t === T_DART ? 2 : t === T_POD ? 3 : t === T_SHELL ? 4 : 5]
      const ex = eX[e]
      const ey = eY[e]
      // A shellback's guard below it takes the shot first.
      const bottom = t === T_SHELL && eGuard[e] > 0 ? ey + spr.h + 2 : ey + spr.h
      if (x < ex || x >= ex + spr.w || y < ey || y >= bottom) continue
      sOn[i] = 0
      if (t === T_SHELL && eGuard[e] > 0) {
        eGuard[e]--
        eFlash[e] = 3
        sparks(x, y, 3, 8)
        if (eGuard[e] === 0) {
          S.score += 50
          sparks(ex + 5, ey + spr.h + 1, 10, 14)
        }
      } else hurt(e, 1)
      break
    }
  }
}

/** Damage to an enemy; at nothing left it goes up in sparks. */
function hurt(e: number, damage: number) {
  const t = eT[e]
  eHP[e] -= damage
  eFlash[e] = 3
  if (t === T_BOSS) bossHP = eHP[e] > 0 ? eHP[e] : 0
  if (eHP[e] > 0) return
  const spr = SPRITES[t === T_MOTH ? 0 : t === T_DART ? 2 : t === T_POD ? 3 : t === T_SHELL ? 4 : 5]
  const cx = eX[e] + (spr.w >> 1)
  const cy = eY[e] + (spr.h >> 1)
  eT[e] = 0
  if (t === T_BOSS) {
    S.score += POINTS[T_BOSS] * ((S.wave / 5) | 0)
    sparks(cx, cy, 60, 30)
    flash = 20
    bOn.fill(0)
    drop(cx - 2, cy, 0)
    drop(cx + 4, cy - 3, 3)
  } else {
    S.score += POINTS[t]
    sparks(cx, cy, t === T_SHELL ? 18 : 10, 20)
    if (t === T_SHELL || rint(100) < 7) drop(cx - 2, cy - 3, rint(100))
  }
  if (S.score >= nextLife) {
    S.lives++
    nextLife += 30000
  }
}

function drop(x: number, y: number, roll: number) {
  for (let i = 0; i < NU; i++) {
    if (uOn[i]) continue
    uOn[i] = 1
    // Spread 35%, rapid 30%, shield 20%, bomb 15%.
    uKind[i] = roll < 35 ? 0 : roll < 65 ? 1 : roll < 85 ? 2 : 3
    uX[i] = x < 0 ? 0 : x > FW - 5 ? FW - 5 : x
    uY[i] = y
    return
  }
}

function movePowerUps() {
  for (let i = 0; i < NU; i++) {
    if (!uOn[i]) continue
    uY[i] += 0.32
    if (uY[i] > FH) {
      uOn[i] = 0
      continue
    }
    if (shipAlive && uX[i] + 5 > shipX && uX[i] < shipX + KESTREL.w && uY[i] + 7 > shipY && uY[i] < shipY + KESTREL.h) {
      uOn[i] = 0
      const k = uKind[i]
      if (k === 0) S.spread = 1
      else if (k === 1) S.rapid = 600
      else if (k === 2) S.shield = true
      else S.bombs = S.bombs < 5 ? S.bombs + 1 : 5
      S.score += 100
      sparks(uX[i] + 2, uY[i] + 3, 8, 10)
    }
  }
  if (S.rapid > 1) S.rapid--
  else if (S.rapid === 1) S.rapid = 0
}

function sparks(x: number, y: number, n: number, life: number) {
  for (let i = 0; i < NP && n > 0; i++) {
    if (pLife[i]) continue
    pLife[i] = life - rint(6)
    pX[i] = x
    pY[i] = y
    const a = rfloat() * 6.283
    const v = 0.25 + rfloat() * 0.9
    pVX[i] = Math.cos(a) * v
    pVY[i] = Math.sin(a) * v
    n--
  }
}

function moveSparks() {
  for (let i = 0; i < NP; i++) {
    if (!pLife[i]) continue
    pLife[i]--
    pX[i] += pVX[i]
    pY[i] += pVY[i]
    pVX[i] *= 0.96
    pVY[i] *= 0.96
  }
}

// --- enemies -------------------------------------------------------------------------------

const SPEED = [0.48, 0.6, 0.75] // bullet speed by difficulty
const RATE = [0.4, 0.8, 1.3] // how often they fire

function spawn() {
  // Who is waiting to come in.
  let waiting = 0
  for (let q = 0; q < NQ; q++) {
    if (qWait[q] < 0) continue
    waiting++
    if (qWait[q]-- > 0) continue
    enemy(qType[q], qX[q], qA[q])
    qWait[q] = -1
  }
  let alive = 0
  for (let i = 0; i < NE; i++) if (eT[i]) alive++
  if (banner > 40) return
  if (squads > 0) {
    if (--squadIn <= 0 || (alive === 0 && waiting === 0)) {
      squad()
      squads--
      squadIn = Math.max(80, 170 - S.wave * 6)
    }
    return
  }
  if (alive === 0 && waiting === 0 && shipAlive && !endIn) {
    // Wave cleared.
    S.score += 100 * S.wave
    startWaveKeepShip(S.wave + 1)
  }
}

function startWaveKeepShip(n: number) {
  const x = shipX
  const y = shipY
  startWave(n)
  shipX = x
  shipY = y
  invulnerable = 0
}

function queue(type: number, wait: number, x: number, a: number) {
  for (let q = 0; q < NQ; q++) {
    if (qWait[q] >= 0) continue
    qWait[q] = wait
    qType[q] = type
    qX[q] = x
    qA[q] = a
    return
  }
}

function squad() {
  const n = S.wave
  if (bossWave) {
    queue(T_BOSS, 0, (FW - BARGE.w) / 2, 0)
    return
  }
  const kinds = n >= 4 ? 4 : n >= 3 ? 3 : n >= 2 ? 2 : 1
  const kind = 1 + rint(kinds)
  if (kind === T_MOTH) {
    const fromLeft = rint(2) === 0
    const count = n > 6 ? 6 : 5
    for (let k = 0; k < count; k++) queue(T_MOTH, k * 14, fromLeft ? FW * 0.3 : FW * 0.7, fromLeft ? 1 : -1)
  } else if (kind === T_DART) {
    const count = n > 7 ? 4 : 3
    for (let k = 0; k < count; k++) queue(T_DART, k * 26, 4 + rint(FW - 12), FH * (0.1 + rfloat() * 0.25))
  } else if (kind === T_POD) {
    queue(T_POD, 0, FW * 0.22, FH * (0.12 + rfloat() * 0.2))
    queue(T_POD, 30, FW * 0.7, FH * (0.12 + rfloat() * 0.2))
  } else {
    queue(T_SHELL, 0, 6 + rint(FW - 20), FH * (0.06 + rfloat() * 0.1))
    for (let k = 0; k < 3; k++) queue(T_MOTH, 30 + k * 14, FW * 0.5, rint(2) ? 1 : -1)
  }
}

function enemy(type: number, x: number, a: number) {
  for (let i = 0; i < NE; i++) {
    if (eT[i]) continue
    const d = S.difficulty
    eT[i] = type
    eAge[i] = 0
    eFlash[i] = 0
    eGuard[i] = 0
    eVX[i] = 0
    eVY[i] = 0
    eFire[i] = 60 + rint(120)
    if (type === T_MOTH) {
      eX[i] = x
      eY[i] = -MOTH_A.h
      eA[i] = x - MOTH_A.w / 2
      eB[i] = a // which way it swings
      eHP[i] = 1
    } else if (type === T_DART) {
      eX[i] = x
      eY[i] = -DART_S.h
      eA[i] = a
      eHP[i] = 1
    } else if (type === T_POD) {
      eX[i] = x - POD_S.w / 2
      eY[i] = -POD_S.h
      eA[i] = a
      eHP[i] = 3 + (d === 2 ? 1 : 0)
    } else if (type === T_SHELL) {
      eX[i] = x
      eY[i] = -SHELL_S.h
      eA[i] = a
      eHP[i] = 2 + (d === 2 ? 1 : 0)
      eGuard[i] = 4
      eVX[i] = rint(2) ? 0.35 : -0.35
    } else {
      eX[i] = x
      eY[i] = -BARGE.h
      eHP[i] = 70 + 35 * (((S.wave / 5) | 0) - 1) + (d === 2 ? 30 : d === 0 ? -20 : 0)
      bossHP = eHP[i]
      bossMax = eHP[i]
      eFire[i] = 90
    }
    return
  }
}

function aim(x: number, y: number, speed: number, spread: number) {
  const dx = shipX + 4 - x
  const dy = shipY + 4 - y
  const len = Math.sqrt(dx * dx + dy * dy) || 1
  bullet(x, y, (dx / len) * speed + spread, (dy / len) * speed)
}

function bullet(x: number, y: number, vx: number, vy: number) {
  for (let i = 0; i < NB; i++) {
    if (bOn[i]) continue
    bOn[i] = 1
    bX[i] = x
    bY[i] = y
    bVX[i] = vx
    bVY[i] = vy
    return
  }
}

function moveEnemies() {
  const d = S.difficulty
  const speed = SPEED[d] * (1 + (S.wave < 20 ? S.wave : 20) * 0.015)
  // Gentle at first: wave 1 fires at about half the rate, wave 12 on at twice.
  const rate = RATE[d] * (0.5 + (S.wave < 12 ? S.wave : 12) * 0.125)
  for (let i = 0; i < NE; i++) {
    const t = eT[i]
    if (!t) continue
    const age = ++eAge[i]
    if (eFlash[i]) eFlash[i]--
    let fire = false
    if (t === T_MOTH) {
      // Down and across, swinging round its centre line.
      eY[i] += 0.38 + S.wave * 0.012
      eX[i] = eA[i] + SIN[((age * 1.385) | 0) & 255] * FW * 0.3 * eB[i]
      if (eY[i] > FH + 2) eT[i] = 0
      fire = rint(1000) < 3 * rate
    } else if (t === T_DART) {
      if (age < 400 && eVY[i] === 0) {
        // In to its height, a wobble while it picks a line, then the dive.
        if (eY[i] < eA[i]) eY[i] += 0.7
        else eX[i] += SIN[((age * 8.15) | 0) & 255] * 0.3
        if (age > 70 + (i * 13) % 60) {
          const dx = shipX - eX[i]
          eVX[i] = dx / 70
          eVY[i] = 0.6
          aim(eX[i] + 3, eY[i] + 8, speed, 0)
        }
      } else {
        eVY[i] += 0.035
        eX[i] += eVX[i]
        eY[i] += eVY[i]
        if (eY[i] > FH + 2 || eX[i] < -8 || eX[i] > FW + 2) eT[i] = 0
      }
    } else if (t === T_POD) {
      if (age < 700) {
        if (eY[i] < eA[i]) eY[i] += 0.45
      } else eY[i] += 0.3
      if (eY[i] > FH + 2) eT[i] = 0
      if (eY[i] >= eA[i] && --eFire[i] <= 0) {
        eFire[i] = (150 / rate) | 0
        const x = eX[i] + 4
        const y = eY[i] + 7
        aim(x, y, speed, 0)
        aim(x, y, speed, -0.25)
        aim(x, y, speed, 0.25)
      }
    } else if (t === T_SHELL) {
      if (eY[i] < eA[i]) eY[i] += 0.4
      else {
        eX[i] += eVX[i]
        if (eX[i] < 1 || eX[i] > FW - SHELL_S.w - 1) eVX[i] = -eVX[i]
      }
      if (age > 1100) eY[i] += 0.5
      if (eY[i] > FH + 2) eT[i] = 0
      if (--eFire[i] <= 0 && eY[i] >= eA[i]) {
        eFire[i] = (110 / rate) | 0
        bullet(eX[i] + 1, eY[i] + 7, 0, speed)
        bullet(eX[i] + 8, eY[i] + 7, 0, speed)
      }
    } else {
      boss(i, age, speed, rate)
    }
    if (fire) aim(eX[i] + 4, eY[i] + 6, speed, 0)
    // Crashing into the ship.
    if (shipAlive && !invulnerable && eT[i]) {
      const spr = SPRITES[t === T_MOTH ? 0 : t === T_DART ? 2 : t === T_POD ? 3 : t === T_SHELL ? 4 : 5]
      if (eX[i] + spr.w > shipX + 1 && eX[i] < shipX + KESTREL.w - 1 && eY[i] + spr.h > shipY + 1 &&
          eY[i] < shipY + KESTREL.h - 1) {
        if (t !== T_BOSS) hurt(i, 99)
        hitShip()
      }
    }
  }
}

function boss(i: number, age: number, speed: number, rate: number) {
  if (eY[i] < 2) {
    eY[i] += 0.3
    return
  }
  eX[i] = (FW - BARGE.w) / 2 + SIN[((age * 0.489) | 0) & 255] * (FW - BARGE.w - 2) * 0.5
  const phase = ((age / 300) | 0) % 3
  if (--eFire[i] > 0) return
  const x = eX[i] + 12
  const y = eY[i] + 12
  if (phase === 0) {
    // A fan.
    eFire[i] = (75 / rate) | 0
    for (let k = -2; k <= 2; k++) bullet(x, y, k * 0.28 * speed, speed)
  } else if (phase === 1) {
    // Aimed pairs from the guns.
    eFire[i] = (48 / rate) | 0
    aim(eX[i] + 2, y, speed * 1.1, 0)
    aim(eX[i] + 22, y, speed * 1.1, 0)
  } else {
    // Darts out of the hold.
    eFire[i] = (190 / rate) | 0
    enemy(T_DART, eX[i] + 2, FH * 0.3)
    enemy(T_DART, eX[i] + 18, FH * 0.3)
  }
}

function moveBullets() {
  for (let i = 0; i < NB; i++) {
    if (!bOn[i]) continue
    bX[i] += bVX[i]
    bY[i] += bVY[i]
    const x = bX[i]
    const y = bY[i]
    if (y > FH || y < -2 || x < -2 || x > FW) {
      bOn[i] = 0
      continue
    }
    if (!shipAlive || invulnerable) continue
    // The ship's heart, a little smaller than its picture: grazing is fair.
    if (x + 2 > shipX + 2 && x < shipX + 7 && y + 2 > shipY + 2 && y < shipY + 8) {
      bOn[i] = 0
      hitShip()
    }
  }
}

function hitShip() {
  if (S.shield) {
    S.shield = false
    invulnerable = 60
    sparks(shipX + 4, shipY + 4, 12, 14)
    return
  }
  sparks(shipX + 4, shipY + 4, 40, 30)
  shipAlive = false
  S.lives--
  S.spread = 0
  S.rapid = 0
  respawn = 100
  flash = 8
  dragging = false
}

// --- what the screen shows besides the field ---------------------------------------------------

/** The bomb's flash: the space color for this moment. */
export function spaceColor(hc: boolean): number {
  if (!flash) return hc ? 0 : 0x070b1e
  if (hc) return flash & 2 ? 0xffffff : 0
  const k = flash * 12
  return ((7 + k) << 16) | ((11 + k) << 8) | (30 + k)
}

let shownScore = -1
let shownLives = -1
let shownBombs = -1
let shownWave = -1
let shownBoss = -1
let best = 0

/** The best score, shown in the strip before the first game. */
export function setBest(n: number) {
  best = n
}

/** The score strip, drawn again only when something on it changed. */
export function drawHud(force: boolean) {
  const bossBar = bossWave && bossHP > 0 ? Math.ceil((bossHP * 40) / bossMax) : -1
  if (!force && shownScore === S.score && shownLives === S.lives && shownBombs === S.bombs && shownWave === S.wave &&
      shownBoss === bossBar) return
  clip(0, 0, cols, rows)
  shownScore = S.score
  shownLives = S.lives
  shownBombs = S.bombs
  shownWave = S.wave
  shownBoss = bossBar
  fill(FX, HY, FW, HH, HUD)
  let s = String(S.score)
  while (s.length < 6) s = '0' + s
  text(s, FX + 1, HY + 1, 1, HUD_TEXT)
  // Lives and bombs from the right.
  let x = FX + FW - 1
  const lives = String(S.lives > 0 ? S.lives : 0)
  x -= textWidth(lives, 1)
  text(lives, x, HY + 1, 1, HUD_TEXT)
  x -= LIFE_S.w + 1
  blit(LIFE_S, x, HY + 2)
  const bombs = String(S.bombs)
  x -= textWidth(bombs, 1) + 3
  text(bombs, x, HY + 1, 1, HUD_TEXT)
  x -= BOMB_S.w + 1
  blit(BOMB_S, x, HY + 2)
  // The middle: the boss's health, or the wave.
  const left = FX + textWidth(s, 1) + 3
  const room = x - 2 - left
  if (bossBar >= 0 && room > 12) {
    fill(left, HY + 2, room, 3, BAR_BACK)
    fill(left, HY + 2, Math.max(1, ((room * bossBar) / 40) | 0), 3, BAR)
  } else {
    const w = S.wave ? 'WAVE ' + S.wave : 'HI ' + best
    if (room > textWidth(w, 1)) text(w, left + ((room - textWidth(w, 1)) >> 1), HY + 1, 1, HUD_DIM)
  }
  clip(FX, FY, FW, FH)
}

/** The game's place, to come back to after the interpreter was dropped. */
export function snapshot() {
  return { score: S.score, lives: S.lives, wave: S.wave, bombs: S.bombs, spread: S.spread, nextLife }
}

export function resume(snap: any, difficulty: number) {
  S.score = snap.score | 0
  S.lives = Math.max(1, snap.lives | 0)
  S.bombs = snap.bombs | 0
  S.spread = snap.spread | 0
  S.rapid = 0
  S.shield = false
  S.difficulty = difficulty
  S.over = false
  nextLife = snap.nextLife | 0 || 30000
  startWave(Math.max(1, snap.wave | 0))
}

/** The enemies for the title screen's roster. */
export const ROSTER: [any, string, number][] = [
  [MOTH_A, 'MOTH', 100], [DART_S, 'DART', 150], [POD_S, 'POD', 250], [SHELL_S, 'SHELLBACK', 400],
]

sources.gfx.ts:
// Drawing into the cells of the 8-bit palette mode: a byte a cell, an index
// into the game's palette. Everything here draws into one target, set with
// target() when the cells are made; every shape is clipped to it. Rows are
// filled with Uint8Array.fill, which is one native memset a run: far cheaper
// than a loop of cell writes in QuickJS.

let C: Uint8Array = new Uint8Array(1)
let CW = 1 // the grid's width: a row's stride
// The clip box: nothing is drawn outside [X0, X1) x [Y0, Y1).
let X0 = 0
let Y0 = 0
let X1 = 1
let Y1 = 1

/** The cells everything draws into: a grid `w` cells wide and `h` high,
 *  clipped to all of it. */
export function target(cells: Uint8Array, w: number, h: number) {
  C = cells
  CW = w
  X0 = 0
  Y0 = 0
  X1 = w
  Y1 = h
}

/** Draw only inside this rectangle (a play area under a score strip). */
export function clip(x: number, y: number, w: number, h: number) {
  X0 = x
  Y0 = y
  X1 = x + w
  Y1 = y + h
}

/** A filled rectangle. */
export function fill(x: number, y: number, w: number, h: number, v: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  if (x0 >= x1) return
  for (let r = y0; r < y1; r++) C.fill(v, r * CW + x0, r * CW + x1)
}

/** One cell. */
export function put(x: number, y: number, v: number) {
  if (x >= X0 && y >= Y0 && x < X1 && y < Y1) C[(y | 0) * CW + (x | 0)] = v
}

/** A button-ish box: a face with a border and its corners cut off (left as
 *  `under`, what the box sits on). */
export function box(x: number, y: number, w: number, h: number, face: number, border: number, under: number) {
  fill(x, y, w, h, border)
  fill(x + 1, y + 1, w - 2, h - 2, face)
  put(x, y, under)
  put(x + w - 1, y, under)
  put(x, y + h - 1, under)
  put(x + w - 1, y + h - 1, under)
}

/** Copies a rectangle from `layer` (cells of the same grid) back into the
 *  target: what a moving thing covered, put back. */
export function restore(layer: Uint8Array, x: number, y: number, w: number, h: number) {
  let x0 = x | 0
  let x1 = (x + w) | 0
  let y0 = y | 0
  let y1 = (y + h) | 0
  if (x0 < X0) x0 = X0
  if (y0 < Y0) y0 = Y0
  if (x1 > X1) x1 = X1
  if (y1 > Y1) y1 = Y1
  for (let r = y0; r < y1; r++) {
    const row = r * CW
    for (let i = row + x0; i < row + x1; i++) C[i] = layer[i]
  }
}

// --- sprites ---------------------------------------------------------------

/** A sprite: `w` x `h` palette indexes, 255 where it is see-through. */
export type Sprite = { w: number; h: number; d: Uint8Array }

/**
 * A sprite from a compact string: rows split by `|`, a character a cell, `.`
 * see-through, and every other character the palette index at its place in
 * `values` for its place in `keys` ("ab", [12, 13]: a is 12, b is 13).
 */
export function sprite(text: string, keys: string, values: number[]): Sprite {
  const lines = text.split('|')
  const h = lines.length
  let w = 0
  for (const line of lines) if (line.length > w) w = line.length
  const d = new Uint8Array(w * h).fill(255)
  for (let y = 0; y < h; y++) {
    const line = lines[y]
    for (let x = 0; x < line.length; x++) {
      const k = keys.indexOf(line[x])
      if (k >= 0) d[y * w + x] = values[k]
    }
  }
  return { w, h, d }
}

/** Draws a sprite with its top left at (x, y). `tint` (when not 255) paints
 *  every solid cell that one index: a flash when something is hit. */
export function blit(s: Sprite, x: number, y: number, tint = 255) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      const v = d[src + sx]
      if (v !== 255) C[dst + sx] = tint === 255 ? v : tint
    }
  }
}

/** Puts back what a sprite at (x, y) covered: only its solid cells, from `layer`. */
export function unblit(s: Sprite, x: number, y: number, layer: Uint8Array) {
  const sw = s.w
  const d = s.d
  x = x | 0
  y = y | 0
  let sx0 = 0
  let sy0 = 0
  let sx1 = sw
  let sy1 = s.h
  if (x < X0) sx0 = X0 - x
  if (y < Y0) sy0 = Y0 - y
  if (x + sx1 > X1) sx1 = X1 - x
  if (y + sy1 > Y1) sy1 = Y1 - y
  for (let sy = sy0; sy < sy1; sy++) {
    const src = sy * sw
    const dst = (y + sy) * CW + x
    for (let sx = sx0; sx < sx1; sx++) {
      if (d[src + sx] !== 255) C[dst + sx] = layer[dst + sx]
    }
  }
}

// --- text ------------------------------------------------------------------

// A 3x5 font, 15 bits a glyph, the top row first and each row's left dot its
// high bit. Letters, digits and a little punctuation; `@` is a heart.
const GLYPHS: Record<string, number> = {
  A: 0x2bed, B: 0x6bae, C: 0x3923, D: 0x6b6e, E: 0x79a7, F: 0x79a4, G: 0x396b, H: 0x5bed, I: 0x7497,
  J: 0x126a, K: 0x5bad, L: 0x4927, M: 0x5fed, N: 0x6b6d, O: 0x2b6a, P: 0x6ba4, Q: 0x2b73, R: 0x6bad,
  S: 0x388e, T: 0x7492, U: 0x5b6f, V: 0x5b6a, W: 0x5bfd, X: 0x5aad, Y: 0x5a92, Z: 0x72a7,
  0: 0x7b6f, 1: 0x2c97, 2: 0x73e7, 3: 0x73cf, 4: 0x5bc9, 5: 0x79cf, 6: 0x79ef, 7: 0x7249, 8: 0x7bef, 9: 0x7bcf,
  '-': 0x01c0, '+': 0x05d0, '<': 0x1511, '>': 0x4454, '.': 0x0002, ':': 0x0410, '/': 0x12a4, ' ': 0,
  '!': 0x2482, '?': 0x7282, "'": 0x2400, ',': 0x0014, '%': 0x52a5, '#': 0x5f7d, '*': 0x0aa8, '=': 0x0e38,
  '(': 0x2922, ')': 0x224a, '@': 0x5fd0, '_': 0x0007,
}

/** A character's 15 dots (0 for one the font lacks). */
export function glyphBits(ch: string): number {
  return GLYPHS[ch] ?? GLYPHS[ch.toUpperCase()] ?? 0
}

/** Cells a line of text takes at `scale`: 4 dots a letter, less the last gap. */
export function textWidth(text: string, scale: number): number {
  return text.length ? (text.length * 4 - 1) * scale : 0
}

/**
 * Text with its top left at (x, y), `scale` cells a dot. With `ramp` each row
 * of dots is one index further from `v` (v, v+1, ... v+4: a gradient down the
 * letters); with `upside` it is turned 180 degrees, for the player across the
 * table.
 */
export function text(s: string, x: number, y: number, scale: number, v: number, ramp = false, upside = false) {
  const n = s.length
  for (let g = 0; g < n; g++) {
    const ch = s[upside ? n - 1 - g : g]
    const bits = glyphBits(ch)
    if (!bits) continue
    const left = x + g * 4 * scale
    for (let i = 0; i < 15; i++) {
      const bit = upside ? i : 14 - i
      if (!(bits & (1 << bit))) continue
      const dotRow = (i / 3) | 0
      fill(left + (i % 3) * scale, y + dotRow * scale, scale, scale, ramp ? v + (upside ? 4 - dotRow : dotRow) : v)
    }
  }
}

/** Text centred on column `cx`. */
export function textCenter(s: string, cx: number, y: number, scale: number, v: number, ramp = false) {
  text(s, cx - ((textWidth(s, scale) / 2) | 0), y, scale, v, ramp)
}

/** A headline: gradient letters (`v` .. `v`+4) over a drop shadow `shadow`. */
export function title(s: string, cx: number, y: number, scale: number, v: number, shadow: number) {
  const x = cx - ((textWidth(s, scale) / 2) | 0)
  const off = scale > 1 ? (scale / 2) | 0 : 1
  text(s, x + off, y + off, scale, shadow)
  text(s, x, y, scale, v, true)
}

// The digits' glyphs, for numbers drawn every frame without making a string.
const DIGITS = new Int32Array(10)
for (let d = 0; d < 10; d++) DIGITS[d] = GLYPHS[String(d)]

/** A whole number at (x, y), at least `width` digits (zeros in front), with
 *  no string made: a speed or a clock drawn every frame. Answers its width. */
export function number(n: number, x: number, y: number, scale: number, v: number, width = 1): number {
  n = n < 0 ? 0 : n | 0
  let count = 1
  for (let k = n; k >= 10; k = (k / 10) | 0) count++
  if (count < width) count = width
  let at = x + (count - 1) * 4 * scale
  for (let i = 0; i < count; i++) {
    const bits = DIGITS[n % 10]
    for (let b = 0; b < 15; b++) {
      if (bits & (1 << (14 - b))) fill(at + (b % 3) * scale, y + ((b / 3) | 0) * scale, scale, scale, v)
    }
    n = (n / 10) | 0
    at -= 4 * scale
  }
  return count * 4 * scale - scale
}

sources.input.ts:
// Input for the games: touch (each finger by its pointerId, so one can hold
// left while another fires), GPIO buttons (down and up the moment they
// happen) and a keyboard, all folded into one set of action bits. What is
// held is held(); a press that came and went between two frames still counts
// once through take(), so a quick tap of a GPIO key is never lost.

export const LEFT = 1
export const RIGHT = 2
export const UP = 4
export const DOWN = 8
export const A = 16
export const B = 32
export const START = 64 // pause / resume / start
export const TAP = 128 // a finger or a click on the play area (not a control)

const ACTIONS: Record<string, number> = {
  left: LEFT, right: RIGHT, up: UP, down: DOWN, a: A, fire: A, b: B, bomb: B, brake: B,
  start: START, pause: START, gas: A, jump: A, button: A,
}

const MAX = 32 // pointer ids are folded into this many slots
const ptrBits = new Uint8Array(MAX)
const ptrDrag = new Uint8Array(MAX)
/** Which pointers are down on the play area (not on a control), by id. */
export const drags = ptrDrag
/** Where each dragging pointer is now and where it went down, in scene pixels. */
export const ptrX = new Int16Array(MAX)
export const ptrY = new Int16Array(MAX)
export const ptrStartX = new Int16Array(MAX)
export const ptrStartY = new Int16Array(MAX)
const pinBits = new Uint8Array(64)
let keyBits = 0
let gpioBits = 0
let latched = 0
let gpioSeen = false
let labels: Record<string, number> = {}
let hitTest: (x: number, y: number) => number = () => 0
// What was used last: 'touch', 'key' or 'gpio'.
let lastKind = ''
let tapX = 0
let tapY = 0

/** How a pointer at (x, y) scene pixels hits the on-screen controls: their
 *  action bits, or 0 for the play area (a drag there). */
export function setHitTest(fn: (x: number, y: number) => number) {
  hitTest = fn
}

/** The "Buttons" setting: `LEFT=left, RIGHT=right, KEY1=a`. Labels (and
 *  roles) are matched without case; a key it does not name is A. */
export function setButtons(spec: string) {
  labels = {}
  for (const part of String(spec || '').split(',')) {
    const eq = part.indexOf('=')
    if (eq < 0) continue
    const name = part.slice(0, eq).trim().toLowerCase()
    const action = ACTIONS[part.slice(eq + 1).trim().toLowerCase()]
    if (name && action) labels[name] = action
  }
}

function gpioAction(payload: any): number {
  const label = String(payload.label || '').toLowerCase()
  const role = String(payload.role || '').toLowerCase()
  return labels[label] || labels[role] || ACTIONS[label] || A
}

/** The default keys: arrows and WASD, Space / Z / J for A, X / K / C for B,
 *  Enter, P and Escape to pause. */
export function keyAction(code: string): number {
  switch (code) {
    case 'ArrowLeft': case 'KeyA': return LEFT
    case 'ArrowRight': case 'KeyD': return RIGHT
    case 'ArrowUp': case 'KeyW': return UP
    case 'ArrowDown': case 'KeyS': return DOWN
    case 'Space': case 'KeyZ': case 'KeyJ': return A
    case 'KeyX': case 'KeyK': case 'KeyC': return B
    case 'Enter': case 'NumpadEnter': case 'KeyP': case 'Escape': return START
  }
  return 0
}

function recount() {
  let g = 0
  for (let i = 0; i < 64; i++) g |= pinBits[i]
  gpioBits = g
}

/**
 * One input event. Answers the action bits it pressed (0 when it pressed
 * nothing, -1 when it was not input at all), so a game can react at once.
 * `keys` maps a key code to bits (keyAction by default).
 */
export function handle(event: string, p: any, keys: (code: string) => number = keyAction): number {
  if (event === 'pointerDown' || event === 'pointerMove') {
    const id = (p.pointerId | 0) & (MAX - 1)
    const x = p.x | 0
    const y = p.y | 0
    if (event === 'pointerMove' && !ptrBits[id] && !ptrDrag[id]) return 0 // a mouse passing over
    lastKind = 'touch'
    if (event === 'pointerDown') {
      const bits = hitTest(x, y)
      ptrBits[id] = bits
      ptrDrag[id] = bits ? 0 : 1
      ptrX[id] = ptrStartX[id] = x
      ptrY[id] = ptrStartY[id] = y
      tapX = x
      tapY = y
      latched |= bits || TAP
      return bits || TAP
    }
    ptrX[id] = x
    ptrY[id] = y
    if (ptrBits[id]) {
      // A thumb sliding from one button to the next presses that one.
      const bits = hitTest(x, y)
      const fresh = bits & ~ptrBits[id]
      ptrBits[id] = bits
      latched |= fresh
      return fresh
    }
    return 0
  }
  if (event === 'pointerUp' || event === 'pointerCancel') {
    const id = (p.pointerId | 0) & (MAX - 1)
    ptrBits[id] = 0
    ptrDrag[id] = 0
    return 0
  }
  if (event === 'keyDown' || event === 'keyUp') {
    const bits = keys(String(p.code || p.key || ''))
    if (!bits) return 0
    lastKind = 'key'
    if (event === 'keyUp') {
      keyBits &= ~bits
      return 0
    }
    if (p.repeat) return 0
    keyBits |= bits
    latched |= bits
    return bits
  }
  if (event === 'gpio') {
    gpioSeen = true
    lastKind = 'gpio'
    const pin = (p.pin | 0) & 63
    if (p.action === 'down') {
      const bits = gpioAction(p)
      pinBits[pin] = bits
      latched |= bits
      recount()
      return bits
    }
    if (p.action === 'up') {
      pinBits[pin] = 0
      recount()
    }
    return 0
  }
  if (event === 'button') {
    // Only where no gpio edges arrive: a press after the release.
    if (gpioSeen || (p.action !== 'press' && p.action !== 'doublePress')) return 0
    lastKind = 'gpio'
    const bits = gpioAction(p)
    latched |= bits
    return bits
  }
  return -1
}

/** Everything held now. */
export function held(): number {
  let bits = keyBits | gpioBits
  for (let i = 0; i < MAX; i++) bits |= ptrBits[i]
  return bits
}

/** Counts as a press of `bits` (a swipe in from an edge that means pause). */
export function press(bits: number) {
  latched |= bits
}

/** The presses since the last call. */
export function take(): number {
  const bits = latched
  latched = 0
  return bits
}

/** The id of a finger dragging on the play area, or -1. */
export function dragging(): number {
  for (let i = 0; i < MAX; i++) if (ptrDrag[i]) return i
  return -1
}

/** Where the last finger or click went down, in scene pixels. */
export function lastTapX(): number {
  return tapX
}
export function lastTapY(): number {
  return tapY
}

/** Every finger lets go (a pause, the scene closing). */
export function releaseAll() {
  ptrBits.fill(0)
  ptrDrag.fill(0)
  pinBits.fill(0)
  keyBits = 0
  gpioBits = 0
  latched = 0
}

/** Whether a keyboard was the last thing used. */
export function usingKeyboard(): boolean {
  return lastKind === 'key'
}

sources.controls.ts:
// The on-screen controls: a D-pad (left/right, or a cross) and up to two
// action buttons, drawn into the cells, with a pause button. On a wide screen
// they sit in panels at both sides (thumbs on a held tablet); on a square or
// tall one in a bar along the bottom. Buttons are at least ~60 px on the
// glass and ~24 px from the screen's edges, where a swipe belongs to the
// frame. The palette indexes they draw with are the kit's UI slots (ui.ts).
import { box, fill, text, textWidth } from './gfx'
import { A, B, DOWN, LEFT, RIGHT, START, UP } from './input'
import { UI_BORDER, UI_EDGE, UI_FACE, UI_ICON, UI_ICON_LIT, UI_LIT, UI_PANEL } from './ui'

const ICON_LEFT = 1
const ICON_RIGHT = 2
const ICON_UP = 3
const ICON_DOWN = 4
const ICON_A = 5
const ICON_B = 6
const ICON_PAUSE = 7

export type Layout = {
  /** The play area, in cells. */
  x: number
  y: number
  w: number
  h: number
  wide: boolean
  /** Buttons: 5 numbers each (bits, x, y, w, h) and an icon. */
  n: number
  b: Int16Array
  icon: Uint8Array
  /** Panels behind the buttons: x, y, w, h each. */
  np: number
  panels: Int16Array
  /** The D-pad's box, which picks a direction by where in it a finger is. */
  dx: number
  dy: number
  dw: number
  dh: number
  dpad: number
  gap: number
  px: number
  labelA: string
  labelB: string
}

/**
 * Where everything goes on a `cols` x `rows` grid of `px`-pixel cells.
 * `dpad` 0 (none), 2 (left and right) or 4 (a cross); `actions` 0, 1 (A) or
 * 2 (A and B); `show` false leaves the whole screen to the game. `sides`
 * false keeps the bar along the bottom on a wide screen too (a wide view).
 */
export function layout(cols: number, rows: number, px: number, dpad: number, actions: number, show: boolean,
    labelA = 'A', labelB = 'B', sides = true): Layout {
  const L: Layout = {
    x: 0, y: 0, w: cols, h: rows, wide: sides && cols >= rows * 1.25, n: 0, b: new Int16Array(40), icon: new Uint8Array(8),
    np: 0, panels: new Int16Array(8), dx: 0, dy: 0, dw: 0, dh: 0, dpad, gap: 1, px, labelA, labelB,
  }
  if (!show) return L
  let bs = Math.max(8, Math.ceil(60 / px)) // a button, in cells
  const edge = Math.max(2, Math.ceil(24 / px)) // kept free along the screen's edges
  const gap = Math.max(1, Math.round(bs / 6))
  L.gap = gap
  if (dpad === 4) bs = Math.max(7, Math.min(bs, Math.floor((rows - 2 * edge) / 3.6)))
  const padW = dpad === 4 ? 3 * bs : dpad === 2 ? 2 * bs + gap : 0
  const padH = dpad === 4 ? 3 * bs : dpad === 2 ? bs : 0
  const actW = actions === 2 ? 2 * bs + gap : actions === 1 ? bs : 0
  const actH = actions === 2 ? bs + (bs >> 1) : actions === 1 ? bs : 0
  const ps = Math.max(6, Math.round(bs * 0.65)) // the pause button
  const add = (bits: number, x: number, y: number, w: number, h: number, icon: number) => {
    const at = L.n * 5
    L.b[at] = bits
    L.b[at + 1] = x
    L.b[at + 2] = y
    L.b[at + 3] = w
    L.b[at + 4] = h
    L.icon[L.n] = icon
    L.n++
  }
  const panel = (x: number, y: number, w: number, h: number) => {
    L.panels.set([x, y, w, h], L.np * 4)
    L.np++
  }
  let padX = 0
  let padY = 0
  let actX = 0
  let actY = 0
  if (L.wide) {
    const side = Math.max(padW, actW, ps) + edge + 2 * gap
    L.x = side
    L.w = cols - 2 * side
    panel(0, 0, side, rows)
    panel(cols - side, 0, side, rows)
    // The thumbs' places: a little below the middle.
    padX = edge
    padY = Math.min(rows - edge - padH, Math.round(rows * 0.58 - padH / 2))
    actX = cols - edge - actW
    actY = Math.min(rows - edge - actH, Math.round(rows * 0.58 - actH / 2))
    add(START, cols - edge - ps, edge, ps, ps, ICON_PAUSE)
  } else {
    const content = Math.max(padH, actH, ps)
    const bar = content + edge + 2 * gap
    L.h = rows - bar
    panel(0, rows - bar, cols, bar)
    padX = edge
    padY = rows - edge - gap - content + ((content - padH) >> 1)
    actX = cols - edge - actW
    actY = rows - edge - gap - content + ((content - actH) >> 1)
    add(START, (cols - ps) >> 1, rows - edge - gap - content + ((content - ps) >> 1), ps, ps, ICON_PAUSE)
  }
  if (dpad === 2) {
    add(LEFT, padX, padY, bs, bs, ICON_LEFT)
    add(RIGHT, padX + bs + gap, padY, bs, bs, ICON_RIGHT)
  } else if (dpad === 4) {
    add(UP, padX + bs, padY, bs, bs, ICON_UP)
    add(LEFT, padX, padY + bs, bs, bs, ICON_LEFT)
    add(RIGHT, padX + 2 * bs, padY + bs, bs, bs, ICON_RIGHT)
    add(DOWN, padX + bs, padY + 2 * bs, bs, bs, ICON_DOWN)
  }
  L.dx = padX
  L.dy = padY
  L.dw = padW
  L.dh = padH
  if (actions === 2) {
    // B up and to the left, A down and to the right, as on a game pad.
    add(B, actX, actY, bs, bs, ICON_B)
    add(A, actX + bs + gap, actY + (bs >> 1), bs, bs, ICON_A)
  } else if (actions === 1) {
    add(A, actX, actY, bs, bs, ICON_A)
  }
  return L
}

/** What a pointer at (x, y) scene pixels presses: action bits, or 0 for the
 *  play area and the bare panels. */
export function hit(L: Layout, x: number, y: number): number {
  const cx = x / L.px
  const cy = y / L.px
  const g = L.gap
  // The D-pad as one pad: a direction by where on it the thumb is, so a
  // thumb rolling across it never falls between two buttons.
  if (L.dpad && cx >= L.dx - g && cx < L.dx + L.dw + g && cy >= L.dy - g && cy < L.dy + L.dh + g) {
    if (L.dpad === 2) return cx < L.dx + L.dw / 2 ? LEFT : RIGHT
    const mx = cx - (L.dx + L.dw / 2)
    const my = cy - (L.dy + L.dh / 2)
    const dead = L.dw / 6
    let bits = 0
    if (mx < -dead) bits |= LEFT
    if (mx > dead) bits |= RIGHT
    if (my < -dead) bits |= UP
    if (my > dead) bits |= DOWN
    return bits
  }
  for (let i = 0; i < L.n; i++) {
    const at = i * 5
    const bits = L.b[at]
    if (bits & (LEFT | RIGHT | UP | DOWN)) continue
    if (cx >= L.b[at + 1] - g && cy >= L.b[at + 2] - g && cx < L.b[at + 1] + L.b[at + 3] + g &&
        cy < L.b[at + 2] + L.b[at + 4] + g) return bits
  }
  return 0
}

/** Panels and every button. */
export function drawControls(L: Layout, held: number) {
  for (let i = 0; i < L.np; i++) {
    const at = i * 4
    const x = L.panels[at]
    const y = L.panels[at + 1]
    const w = L.panels[at + 2]
    const h = L.panels[at + 3]
    fill(x, y, w, h, UI_PANEL)
    // A line along the side that meets the play area.
    if (L.wide) fill(x === 0 ? x + w - 1 : x, y, 1, h, UI_EDGE)
    else fill(x, y, w, 1, UI_EDGE)
  }
  for (let i = 0; i < L.n; i++) drawButton(L, i, (held & L.b[i * 5]) !== 0)
}

/** Draws again only the buttons whose state changed between `was` and `now`. */
export function updateControls(L: Layout, was: number, now: number) {
  const changed = was ^ now
  if (!changed) return
  for (let i = 0; i < L.n; i++) if (changed & L.b[i * 5]) drawButton(L, i, (now & L.b[i * 5]) !== 0)
}

function drawButton(L: Layout, i: number, lit: boolean) {
  const at = i * 5
  const x = L.b[at + 1]
  const y = L.b[at + 2]
  const w = L.b[at + 3]
  const h = L.b[at + 4]
  box(x, y, w, h, lit ? UI_LIT : UI_FACE, UI_BORDER, UI_PANEL)
  const ink = lit ? UI_ICON_LIT : UI_ICON
  const cx = x + (w >> 1)
  const cy = y + (h >> 1) + (lit ? 1 : 0)
  const icon = L.icon[i]
  const r = Math.max(2, Math.round(w * 0.22))
  if (icon <= ICON_DOWN) arrow(icon, cx, cy, r, ink)
  else if (icon === ICON_PAUSE) {
    const bw = Math.max(1, Math.round(w / 7))
    fill(cx - bw - Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
    fill(cx + Math.max(1, bw >> 1), cy - r, bw, 2 * r, ink)
  } else {
    const label = icon === ICON_A ? L.labelA : L.labelB
    // Letters about half the button's height, as wide as fit.
    let scale = Math.max(1, Math.floor((h * 0.5) / 5 + 0.5))
    while (scale > 1 && textWidth(label, scale) > w - 4) scale--
    text(label, cx - ((textWidth(label, scale) / 2) | 0), cy - ((5 * scale) >> 1), scale, ink)
  }
}

/** A filled triangle pointing `dir`, `r` cells from its tip to its base,
 *  centred on (cx, cy). */
function arrow(dir: number, cx: number, cy: number, r: number, v: number) {
  const half = (r + 1) >> 1
  for (let i = 0; i <= r; i++) {
    // i: how far from the tip; the span widens by one each side per step.
    if (dir === ICON_LEFT) fill(cx - half + i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_RIGHT) fill(cx + half - i, cy - i, 1, 2 * i + 1, v)
    else if (dir === ICON_UP) fill(cx - i, cy - half + i, 2 * i + 1, 1, v)
    else fill(cx - i, cy + half - i, 2 * i + 1, 1, v)
  }
}

sources.ui.ts:
// What the games share besides drawing and input: the palette slots of the
// controls and screens, the contrast rule, the cell size, the fixed-step
// clock, the random numbers, the high score table and the title, pause and
// game over screens. A game's own colors use palette indexes 0..223; the kit
// owns 224..255.
import { box, fill, textCenter, textWidth, title } from './gfx'

export const UI_TITLE = 224 // .. 228, a gradient down the title's letters
export const UI_SHADOW = 229
export const UI_ICON_LIT = 230
export const UI_PANEL = 231
export const UI_EDGE = 232
export const UI_BORDER = 233
export const UI_FACE = 234
export const UI_LIT = 235
export const UI_ICON = 236
export const UI_TEXT = 237
export const UI_DIM = 238
export const UI_BLINK = 239 // text that blinks: its color flips, no cell changes
export const UI_DIALOG = 240
export const UI_DIALOG_EDGE = 241
export const UI_ACCENT = 242
export const UI_GOOD = 243 // a new high score

/** A game's colors for the kit's slots, 0xRRGGBB. */
export type Theme = {
  title: number[] // five, top to bottom
  shadow: number
  panel: number
  edge: number
  border: number
  face: number
  lit: number
  icon: number
  iconLit: number
  text: number
  dim: number
  dialog: number
  dialogEdge: number
  accent: number
  good: number
}

const WHITE = 0xffffff
const BLACK = 0x000000

/** The kit's slots of `pal`, in the theme's colors or in black and white. */
export function uiColors(pal: Uint32Array, t: Theme, hc: boolean) {
  for (let i = 0; i < 5; i++) pal[UI_TITLE + i] = hc ? WHITE : t.title[i]
  pal[UI_SHADOW] = hc ? BLACK : t.shadow
  pal[UI_ICON_LIT] = hc ? BLACK : t.iconLit
  pal[UI_PANEL] = hc ? BLACK : t.panel
  pal[UI_EDGE] = hc ? WHITE : t.edge
  pal[UI_BORDER] = hc ? WHITE : t.border
  pal[UI_FACE] = hc ? BLACK : t.face
  pal[UI_LIT] = hc ? WHITE : t.lit
  pal[UI_ICON] = hc ? WHITE : t.icon
  pal[UI_TEXT] = hc ? WHITE : t.text
  pal[UI_DIM] = hc ? WHITE : t.dim
  pal[UI_BLINK] = hc ? WHITE : t.text
  pal[UI_DIALOG] = hc ? BLACK : t.dialog
  pal[UI_DIALOG_EDGE] = hc ? WHITE : t.dialogEdge
  pal[UI_ACCENT] = hc ? WHITE : t.accent
  pal[UI_GOOD] = hc ? WHITE : t.good
}

/** "Press A" text blinks by its palette entry alone. */
export function blink(pal: Uint32Array, now: number, on: number, off: number) {
  pal[UI_BLINK] = ((now / 450) | 0) & 1 ? off : on
}

// --- settings --------------------------------------------------------------

/** High contrast where the panel shows no color, or when asked. */
export function highContrast(contrast: any, frame: any): boolean {
  const mode = contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && frame.color === false)
}

/** Whether the panel can animate (an LCD, HDMI) rather than e-paper. */
export function fastScreen(frame: any): boolean {
  return frame.fast ?? !frame.paper
}

/** The "Pixel size" setting: a number, or about `across` cells over the
 *  short side for "auto". */
export function cellSize(setting: any, width: number, height: number, across: number): number {
  const asked = Number(setting) | 0
  if (asked >= 1) return Math.min(16, asked)
  return Math.max(2, Math.round(Math.min(width, height) / across))
}

/** One of `allowed`, else the first. */
export function choice(value: any, allowed: string[]): string {
  const s = String(value ?? '')
  return allowed.indexOf(s) >= 0 ? s : allowed[0]
}

// --- the clock ---------------------------------------------------------------

let last = 0
let owed = 0

/**
 * How many fixed steps of `stepMs` to run this frame, from the wall clock, so
 * the game keeps its speed at 12 fps and at 40. At most `cap` (a slow frame
 * slows the game rather than jumping it), none after a long gap (a pause, a
 * sleep).
 */
export function stepsDue(now: number, stepMs: number, cap: number): number {
  let gap = now - last
  last = now
  if (gap < 0 || gap > 400) gap = stepMs
  owed += gap
  let n = (owed / stepMs) | 0
  owed -= n * stepMs
  if (n > cap) {
    n = cap
    owed = 0
  }
  return n
}

/** Start counting from now (a new game, a resume). */
export function clockReset(now: number) {
  last = now
  owed = 0
}

// --- random numbers ----------------------------------------------------------

let seed = 1

export function reseed(s: number) {
  seed = s | 0 || 0x2545f491
}

/** An xorshift32: a 32-bit integer. */
export function rnd(): number {
  seed ^= seed << 13
  seed ^= seed >>> 17
  seed ^= seed << 5
  return seed
}

/** 0 .. n-1. */
export function rint(n: number): number {
  return ((rnd() >>> 0) % n) | 0
}

/** [0, 1). */
export function rfloat(): number {
  return (rnd() >>> 0) / 4294967296
}

// --- high scores -------------------------------------------------------------

/** The top five from the private `highScores` field (a JSON list of numbers). */
export function readScores(raw: any): number[] {
  let list = raw
  if (typeof list === 'string') {
    try {
      list = JSON.parse(list)
    } catch (e) {
      list = null
    }
  }
  const out: number[] = []
  if (Array.isArray(list)) for (const n of list) if (typeof n === 'number' && n > 0) out.push(n | 0)
  out.sort((a, b) => b - a)
  return out.slice(0, 5)
}

/** Puts `score` in the table: its place (0 = best), or -1 when it is not in
 *  the top five. Saves the table when it changed. */
export function addScore(list: number[], score: number): number {
  if (score <= 0) return -1
  let at = 0
  while (at < list.length && list[at] >= score) at++
  if (at >= 5) return -1
  list.splice(at, 0, score | 0)
  if (list.length > 5) list.length = 5
  frameos.setState('highScores', list.slice())
  return at
}

// --- screens -----------------------------------------------------------------

/** A dialog box: a border and a face. */
export function dialog(x: number, y: number, w: number, h: number) {
  fill(x, y, w, h, UI_DIALOG_EDGE)
  fill(x + 1, y + 1, w - 2, h - 2, UI_DIALOG)
}

/** The scale of the font that fits `chars` letters across `width` cells, at
 *  most `max`. */
export function fitScale(chars: number, width: number, max: number): number {
  return Math.max(1, Math.min(max, Math.floor(width / (chars * 4))))
}

/** The high score table, centred on `cx` from `y`: answers the rows it took. */
export function drawScores(list: number[], cx: number, y: number, scale: number, highlight = -1, label = 'HIGH SCORES'): number {
  textCenter(label, cx, y, scale, UI_ACCENT)
  if (!list.length) {
    textCenter('NONE YET', cx, y + 7 * scale, scale, UI_DIM)
    return 12 * scale
  }
  for (let i = 0; i < list.length; i++) {
    const line = String(i + 1) + '. ' + pad(list[i], 7)
    textCenter(line, cx, y + (7 + i * 7) * scale, scale, i === highlight ? UI_GOOD : UI_TEXT)
  }
  return (7 + list.length * 7) * scale
}

function pad(n: number, width: number): string {
  let s = String(n)
  while (s.length < width) s = ' ' + s
  return s
}

// The pause dialog's two buttons, for tapping: x, y, w, h each.
const choiceBoxes = new Int16Array(8)

/**
 * The pause dialog over the play area (x, y, w, h): PAUSED, and Resume and
 * Quit as big buttons. `hint` is a line of the keys, shown where it fits.
 * Another headline, a line under it and other buttons make it another
 * two-way choice (a rematch or the menu).
 */
export function drawPause(x: number, y: number, w: number, h: number, hint: string, head = 'PAUSED', line = '',
    first = 'RESUME', second = 'QUIT') {
  // Rows it takes at text scale s: 3 + 10 (the title, twice as big) + 4 + 11 + 3 + 11 + 3, 7 for the line
  // and 8 for the hint.
  const extra = line ? 7 : 0
  const s = Math.max(1, Math.min(Math.floor((w - 6) / 34), Math.floor((h - 4) / (45 + extra))))
  const ts = Math.max(1, Math.min(4, 2 * s, Math.floor((w - 8) / (head.length * 4))))
  const withHint = hint && h - 4 >= (45 + extra) * s + 8 && textWidth(hint, 1) <= w - 6
  const dw = Math.min(w - 2, Math.max(34 * s, textWidth(head, ts) + 6 * s, textWidth(line, s) + 6 * s,
    withHint ? textWidth(hint, 1) + 6 : 0))
  const dh = (45 + extra) * s + (withHint ? 8 : 0)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, ts, UI_TITLE, UI_SHADOW)
  const bw = dw - 6 * s
  const bh = 11 * s
  const bx = dx + 3 * s
  let by = dy + 3 * s + 5 * ts + 4 * s
  if (line) {
    textCenter(line, cx, by - s, s, UI_TEXT)
    by += 7 * s
  }
  for (let i = 0; i < 2; i++) {
    box(bx, by, bw, bh, UI_FACE, UI_BORDER, UI_DIALOG)
    textCenter(i === 0 ? first : second, cx, by + 3 * s, s, UI_ICON)
    choiceBoxes[i * 4] = bx
    choiceBoxes[i * 4 + 1] = by
    choiceBoxes[i * 4 + 2] = bw
    choiceBoxes[i * 4 + 3] = bh
    by += bh + 3 * s
  }
  if (withHint) textCenter(hint, cx, dy + dh - 7, 1, UI_DIM)
}

/** Which of the pause dialog's buttons a tap at cell (cx, cy) is on: 1 Resume, 2 Quit, 0 neither. */
export function pauseChoice(cx: number, cy: number): number {
  for (let i = 0; i < 2; i++) {
    const at = i * 4
    if (cx >= choiceBoxes[at] && cy >= choiceBoxes[at + 1] && cx < choiceBoxes[at] + choiceBoxes[at + 2] &&
        cy < choiceBoxes[at + 1] + choiceBoxes[at + 3]) return i + 1
  }
  return 0
}

/**
 * Game over in a dialog over (x, y, w, h): the headline, a line or two about
 * the game, a new high score's place, as much of the table as fits, and
 * "tap" once `ready`.
 */
export function drawGameOver(x: number, y: number, w: number, h: number, head: string, lines: string[],
    rank: number, list: number[], ready: boolean, prompt = 'TAP OR PRESS A') {
  let widest = 15
  for (const line of lines) if (line.length > widest) widest = line.length
  const s = Math.max(1, Math.min(Math.floor((w - 6) / (widest * 4 + 4)), Math.floor((h - 4) / 60)))
  const big = Math.max(1, Math.min(2 * s, Math.floor((w - 8) / (head.length * 4))))
  // Rows: padding, the headline, the lines, the high score line, "tap".
  let need = 3 * s + 5 * big + 4 * s + lines.length * 7 * s + (rank >= 0 ? 7 * s : 0) + 9 * s
  const room = h - 4 - need - 7 * s
  const shown = Math.max(0, Math.min(list.length, Math.floor(room / (7 * s))))
  if (shown) need += (7 + shown * 7) * s + 2 * s
  const dw = Math.min(w - 2, Math.max(textWidth(head, big) + 8 * s, (widest * 4 + 4) * s))
  const dh = Math.min(h - 2, need)
  const dx = x + ((w - dw) >> 1)
  const dy = y + ((h - dh) >> 1)
  dialog(dx, dy, dw, dh)
  const cx = dx + (dw >> 1)
  title(head, cx, dy + 3 * s, big, UI_TITLE, UI_SHADOW)
  let ty = dy + 3 * s + 5 * big + 4 * s
  for (const line of lines) {
    textCenter(line, cx, ty, s, UI_TEXT)
    ty += 7 * s
  }
  if (rank >= 0) {
    textCenter(rank === 0 ? 'NEW HIGH SCORE!' : 'A HIGH SCORE!', cx, ty, s, UI_GOOD)
    ty += 7 * s
  }
  if (shown) {
    ty += 2 * s
    drawScores(list.slice(0, shown), cx, ty, s, rank)
  }
  if (ready) textCenter(prompt, cx, dy + dh - 8 * s, s, UI_BLINK)
}

/** For a screen that cannot animate (e-paper): what the game is and what it needs. */
export function drawSlowCard(cols: number, rows: number, name: string, about: string[], list: number[] | null) {
  fill(0, 0, cols, rows, UI_PANEL)
  const scale = fitScale(name.length + 2, cols - 4, 6)
  const small = fitScale(30, cols - 4, 3)
  // Everything in the middle of the screen.
  const tall = 8 * scale + about.length * 7 * small + (list ? (11 + Math.max(1, list.length) * 7) * small : 0)
  let y = Math.max(2, (rows - tall) >> 1)
  title(name, cols >> 1, y, scale, UI_TITLE, UI_SHADOW)
  y += 8 * scale
  for (const line of about) {
    textCenter(line, cols >> 1, y, small, UI_TEXT)
    y += 7 * small
  }
  y += 4 * small
  if (list) drawScores(list, cols >> 1, y, small)
}
